// Normalização e Motor de Detecção de Bugs
const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;
  const title = data.title || 'Produto em Promoção';
  const currentPrice = Number(data.price || data.current_price || 0);
  const originalPrice = Number(data.original_price || data.regular_price || 0);

  if (currentPrice <= 0 || originalPrice <= 0) continue;

  const discount = ((originalPrice - currentPrice) / originalPrice) * 100;
  const ratio = currentPrice / originalPrice;

  // Heurística de Bug de Preço e Erro de Dígito
  let isBug = false;
  let priority = 'NORMAL';
  let score = Math.floor(discount);

  if (discount >= 80 || ratio <= 0.15) {
    isBug = true;
    priority = 'CRITICAL_BUG';
    score = 98;
  } else if (discount >= 60) {
    isBug = true;
    priority = 'HIGH';
    score = 85;
  }

  if (isBug || score >= 60) {
    results.push({
      json: {
        category: 'price_bug',
        title: title,
        description: `Queda brusca de ${discount.toFixed(1)}% OFF! De R$ ${originalPrice.toFixed(2)} por R$ ${currentPrice.toFixed(2)}`,
        original_price: originalPrice,
        opportunity_price: currentPrice,
        discount_percentage: Number(discount.toFixed(2)),
        net_profit_estimate: Number((originalPrice - currentPrice).toFixed(2)),
        fipe_or_market_ref: originalPrice,
        source_name: data.source || 'E-Commerce Radar',
        source_url: data.url || 'https://exemplo.com',
        affiliate_url: data.affiliate_url || data.url,
        evaluation_score: score,
        priority: priority,
        raw_metadata: {
          isBug,
          ratio: Number(ratio.toFixed(3))
        }
      }
    });
  }
}

return results;
